          { id: "p2", data: "2026-02-10", projeto_id: "CBP-26 002", empresa: "Indústria Alimentícia Pernambucana", objeto: "Reestruturação Tributária e Pleito SUDENE 75% IRPJ", instituicao: "SUDENE", local: "Jaboatão dos Guararapes/PE", fase: "Aprovação", status: "Concluído", captacao: 18000000.0, fee_percent: 0.05, nf: 102, parceiros: 50000.0, despesas_captacao: 20000.0, descricao_despesas: "Auditoria contábil prévia" },
          { id: "p3", data: "2026-02-28", projeto_id: "CBP-26 003", empresa: "Logística Portuária de Suape", objeto: "Emissão de Debêntures Incentivadas Lei 12.431", instituicao: "Mercado de Capitais", local: "Ipojuca/PE", fase: "Estruturação", status: "Em Andamento", captacao: 60000000.0, fee_percent: 0.025, nf: 103, parceiros: 200000.0, despesas_captacao: 80000.0, descricao_despesas: "Roadshow e estruturação de covenants" },
          { id: "p4", data: "2026-03-01", projeto_id: "CBP-26 004", empresa: "Consórcio Municipal de Iluminação Pública", objeto: "Modelagem de Parceria Público-Privada (PPP)", instituicao: "Caixa / BNDES", local: "Caruaru/PE", fase: "Modelagem", status: "Em Andamento", captacao: 25000000.0, fee_percent: 0.04, nf: 104, parceiros: 80000.0, despesas_captacao: 30000.0, descricao_despesas: "Estudos de viabilidade técnica e financeira" }
