      create: async (p) => {
        p.id = "p_" + Date.now();
        const cur = await Jt.entities.Projeto.list();
        cur.unshift(p);
        localStorage.setItem("capibaribe_projetos", JSON.stringify(cur));
        try { fetch("http://localhost:8080/api/v1/projetos", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(p) }); } catch(e) {}
        return p;
      },
      update: async (id, p) => {
        const cur = await Jt.entities.Projeto.list();
        const idx = cur.findIndex(x => x.id === id);
        if (idx !== -1) cur[idx] = { ...cur[idx], ...p };
        localStorage.setItem("capibaribe_projetos", JSON.stringify(cur));
        try { fetch("http://localhost:8080/api/v1/projetos/" + id, { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(p) }); } catch(e) {}
        return cur[idx];
      },
      delete: async (id) => {
        const cur = await Jt.entities.Projeto.list();
        const filtered = cur.filter(x => x.id !== id);
        localStorage.setItem("capibaribe_projetos", JSON.stringify(filtered));
        try { fetch("http://localhost:8080/api/v1/projetos/" + id, { method: "DELETE" }); } catch(e) {}
        return true;
      }
